export const SUMMARY_CSS = ":root {\n  /* Color Palette - Scheme #2 \"Scholar blue\" Light Theme */\n  --primary-color: #2563eb;\n  --primary-dark: #1d4ed8;\n  --primary-light: #3b82f6;\n  --secondary-color: #16a34a;\n  --secondary-dark: #166534;\n  --accent-color: #2563eb;\n  --accent-light: #3b82f6;\n  /* Short aliases: several stylesheets (Summaries.css, Signup.jsx, and more)\n     already read var(--accent)/var(--muted) directly. These used to resolve\n     only by accident — whichever page's own unscoped `:root { --accent: ... }`\n     happened to load last in the session — so the same page could render a\n     different accent color depending on navigation history. One real\n     definition here removes that. */\n  /* Points at --primary-color, not --accent-light. --accent is read as a TEXT\n     colour in 21 places (landing links, .link-primary on login/signup, quiz\n     hub headings, the whole summaries hub); at #3b82f6 every one of those\n     measured 3.68:1, under the 4.5 AA floor. #2563eb measures 5.17:1 and is\n     the same brand blue. --accent-light is still available by name for the\n     fills, hover tints and focus borders that actually want the lighter step. */\n  --accent: var(--primary-color);\n  --muted: var(--text-light);\n  /* --accent-strong had no :root value at all, only page-scoped ones on\n     .landing-body / .login-body / .quiz-selection. Login.css's shared\n     `.btn.primary { background: linear-gradient(135deg, var(--accent), var(--accent-strong)) }`\n     is imported by pages that use none of those roots (GroupsPage's\n     .groups-page, AccountPage's .account-page), where the unresolvable\n     reference made the whole `background` invalid at computed-value time —\n     i.e. transparent, under white text. That is a CTA nobody can see, which\n     is exactly what /groups and /account were shipping. */\n  --accent-strong: var(--primary-color);\n\n  /* Neutral Colors - Light Theme */\n  --text-dark: #0f1e3d;\n  --text-medium: #475569;\n  /* Was #64748b (slate-500). That clears 4.5:1 on pure white, but this app's\n     pages are not white — --bg is #eef2fb, and cards sit on --surface-2 —\n     where it measured 4.24-4.47:1 against real rendered backgrounds. Since\n     this is the default colour for every secondary label, hint, placeholder\n     and caption in the product, that was a systemic AA near-miss on every\n     page. #5b6779 measures 5.08:1 on --bg and 5.74:1 on white, and is still\n     clearly lighter than --text-medium so the hierarchy is intact. */\n  --text-light: #5b6779;\n  --bg-light: #eef2fb;\n  --bg-white: #ffffff;\n  --border-color: #d4deee;\n  --border-light: #e6ecf7;\n\n  /* Semantic surfaces */\n  --bg: #eef2fb;\n  --surface: #ffffff;\n  --surface-2: #f5f8fd;\n  --surface-tint: #e1eafb;\n\n  /* Global defaults for the four short names that .landing-body, .login-body\n     and .quiz-selection each redefine locally. They previously existed ONLY on\n     those three roots, which meant any rule reading them from outside one\n     resolved to nothing — and an unresolvable var() does not fall back, it\n     makes the whole declaration `unset` at computed-value time. A missing\n     --border inside `border: 1px solid var(--border)` is not a default border,\n     it is NO border; a missing --card is a transparent card. Defining them\n     here turns every page-scoped copy into a deliberate refinement instead of\n     a load-bearing requirement, so a shared rule can never blank out because\n     of where it happened to render. */\n  --card: var(--surface);\n  --text: var(--text-dark);\n  --border: var(--border-color);\n  --shadow: var(--shadow-lg);\n  --glass: var(--surface-2);\n\n  /* Status Colors (tuned for light backgrounds) */\n  --success-color: #16a34a;\n  --error-color: #dc2626;\n  --warning-color: #d97706;\n  --info-color: #2563eb;\n\n  /* Shadows - soft for light theme */\n  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.06);\n  --shadow-md: 0 4px 14px rgba(15, 23, 42, 0.10);\n  --shadow-lg: 0 14px 36px rgba(15, 23, 42, 0.16);\n\n  /* Border Radius */\n  --radius-sm: 8px;\n  --radius-md: 12px;\n  --radius-lg: 16px;\n  --radius-xl: 24px;\n\n  /* Typography — both faces are self-hosted via @fontsource (see main.jsx).\n     --font-family-primary switches between them on [lang] below, so every\n     existing var(--font-family-primary) consumer gets the right face for\n     the current site language without being touched individually. */\n  --font-family-latin: 'Inter', system-ui, -apple-system, sans-serif;\n  --font-family-ar: 'Cairo', 'Inter', system-ui, -apple-system, sans-serif;\n  --font-family-primary: var(--font-family-latin);\n  --font-family-secondary: var(--font-family-latin);\n  --font-family-inter: 'Inter', sans-serif;\n\n  /* Height of the fixed app bar, at this breakpoint.\n     Three separate rules have to agree on this number — `.navbar`'s\n     min-height, `.navbar-left`'s height, and `.page-with-navbar`'s\n     padding-top — and when they were maintained by hand they drifted:\n     Navbar.css carried TWO competing sets of padding-top rules (56/52/48 and\n     64/56/52), and only the second set won, purely because it appeared later\n     in the file. Reordering the file would have shifted every page 8px under\n     the navbar. Deriving all three from one token makes that class of drift\n     impossible. The bar also carries a 1px border-bottom, which is why the\n     page offset is `calc(var(--navbar-h) + 1px)` and not the bare value. */\n  --navbar-h: 72px;\n\n  /* Elevation: the layer a fixed navbar sits at. Kept distinct from\n     --z-modal-backdrop/--z-modal (below) specifically so the two can never\n     collide — a modal opened on any page is guaranteed to render above the\n     navbar, never under it. */\n  --z-navbar: 1030;\n\n  /* Accuracy ramp — one shared source for \"how well is this student doing\",\n     instead of the five different hardcoded palettes (three different greens,\n     three different reds) previously scattered across quiz review screens. */\n  --accuracy-high: #16a34a;\n  --accuracy-high-bg: rgba(22, 163, 74, 0.12);\n  --accuracy-mid: #d97706;\n  --accuracy-mid-bg: rgba(217, 119, 6, 0.12);\n  --accuracy-low: #dc2626;\n  --accuracy-low-bg: rgba(220, 38, 38, 0.12);\n\n  /* Shared keyboard-focus ring, for every interactive element that currently\n     sets outline:none with nothing to replace it. */\n  --focus-ring: 0 0 0 3px rgba(59, 130, 246, 0.35);\n\n  /* Font Sizes */\n  --text-xs: 0.75rem;\n  /* 12px */\n  --text-sm: 0.875rem;\n  /* 14px */\n  --text-base: 1rem;\n  /* 16px */\n  --text-lg: 1.125rem;\n  /* 18px */\n  --text-xl: 1.25rem;\n  /* 20px */\n  --text-2xl: 1.5rem;\n  /* 24px */\n  --text-3xl: 1.875rem;\n  /* 30px */\n  --text-4xl: 2.25rem;\n  /* 36px */\n  --text-5xl: 3rem;\n  /* 48px */\n\n  /* Spacing */\n  --space-1: 0.25rem;\n  /* 4px */\n  --space-2: 0.5rem;\n  /* 8px */\n  --space-3: 0.75rem;\n  /* 12px */\n  --space-4: 1rem;\n  /* 16px */\n  --space-5: 1.25rem;\n  /* 20px */\n  --space-6: 1.5rem;\n  /* 24px */\n  --space-8: 2rem;\n  /* 32px */\n  --space-10: 2.5rem;\n  /* 40px */\n  --space-12: 3rem;\n  /* 48px */\n  --space-16: 4rem;\n  /* 64px */\n  --space-20: 5rem;\n  /* 80px */\n\n  /* Page containers.\n     Ten pages hardcoded ten different max-widths (460/480/600/620/650/800/\n     860/960/1100/1400) and their own block padding, which is why nothing\n     stayed consistent between them — there was no shared answer to \"how wide\n     is a page\". Three widths cover every layout in the app:\n       --container-card  a single-column centred card (auth, checkout)\n       --container-form  a card whose fields sit side by side (contact,\n                         suggestions, account) — wider than --container-card\n                         precisely because a 1fr 1fr row inside a 480px card\n                         leaves each field too narrow to type a name into\n       --container-page  one column of prose or a short grid (legal, guides)\n       --container-wide  a dashboard or multi-column grid (FAQ, quiz hub)\n     --page-pad-block is the space between the fixed navbar and the first\n     content. It does NOT need to include the navbar's own height:\n     .page-with-navbar already reserves that with padding-top. Pages that added\n     their own 90-100px on top are the ones that opened with a screenful of\n     nothing. */\n  --container-card: 480px;\n  --container-form: 620px;\n  --container-page: 860px;\n  --container-wide: 1100px;\n  --page-pad-block: clamp(1.25rem, 3vw, 2.5rem);\n  --page-pad-inline: clamp(1rem, 3vw, 1.5rem);\n\n  /* Transitions */\n  --transition-fast: 0.15s ease;\n  --transition-normal: 0.25s ease;\n  --transition-slow: 0.3s ease;\n\n  /* The properties a hover/focus/active state actually changes. Use with the\n     transition-* longhands instead of `transition: all`:\n\n       transition-property: var(--transition-props);\n       transition-duration: 0.2s;\n       transition-timing-function: ease;\n\n     `all` was used in ~93 rules. It animates EVERY animatable property,\n     including layout ones — so a rule that also changes padding, width or\n     font-size on hover animated those too, and any property changed by a\n     media query or by JS transitioned as well. Naming the set keeps every\n     intended effect (colour, elevation, movement, fade, blur) and drops the\n     unintended layout tweening. */\n  --transition-props: background-color, background-image, border-color, color,\n    box-shadow, transform, opacity, filter, backdrop-filter;\n\n  /* Z-index.\n     One ladder for the whole app. Every `position: fixed` overlay must take\n     its value from here — a raw number is how six different full-screen\n     modals ended up at 1000, i.e. UNDER the 1030 navbar, with the navbar\n     still clickable through the backdrop.\n\n       dropdown  1000  menu attached to a trigger (navbar user menu)\n       sticky    1020  in-page sticky headers\n       navbar    1030  the one fixed app bar            (= --z-fixed)\n       backdrop  1040  a modal's dimmer — above the navbar, by definition\n       modal     1050  the modal's own card\n       popover   1060  a popover raised from inside a modal\n       tooltip   1070  never blocks anything\n       banner    1080  app-level banners mounted OUTSIDE the router\n                       (cookie consent, install prompt) — these gate the whole\n                       app, so they intentionally outrank an open modal.\n\n     Anything that needs to sit between two rungs should get a named rung\n     here rather than a hardcoded offset. */\n  --z-dropdown: 1000;\n  --z-sticky: 1020;\n  --z-fixed: 1030;\n  --z-modal-backdrop: 1040;\n  --z-modal: 1050;\n  --z-popover: 1060;\n  --z-tooltip: 1070;\n  --z-banner: 1080;\n}\n\n\n.summary-card.is-soon {\n    cursor: default;\n    opacity: 0.72;\n}\n\n.summary-card.is-soon:hover {\n    transform: none;\n    border-color: #d4deee;\n    box-shadow: none;\n}\n\n.summary-tab.active {\n    background: #236ded;\n    color: #ffffff;\n}\n\n.sum-doc { line-height: 1.7; color: #1e293b; }\n.sum-head h2 { color: #0f1e3d; font-size: 1.5rem; margin: 0 0 8px; }\n.sum-meta { color: var(--text-light); font-size: 0.84rem; margin: 0 0 6px; }\n.sum-doc section.topic {\n    margin: 16px 0;\n    padding: 16px 18px;\n    background: #ffffff;\n    border: 1px solid #d4deee;\n    border-radius: 12px;\n}\n.sum-doc h3 {\n    color: var(--primary-dark);\n    font-size: 1.12rem;\n    margin: 0 0 10px;\n    border-bottom: 1px solid #d4deee;\n    padding-bottom: 6px;\n}\n/* #93c5fd was too light to read against the white study panel (it fails\n   contrast on body-size text); the medical decks sidestep it by tagging every\n   sub-heading .deck-topic. Darkened so a bare <h4> is legible either way. */\n.sum-doc h4 { color: #1d4ed8; font-weight: 700; font-size: 0.96rem; margin: 14px 0 6px; }\n.sum-doc ul, .sum-doc ol { margin: 6px 0; padding-inline-start: 22px; }\n.sum-doc li { margin: 4px 0; font-size: 0.89rem; }\n.sum-doc b { color: #1e293b; }\n.sum-callout {\n    background: rgba(35, 109, 237, 0.08);\n    border: 1px solid rgba(35, 109, 237, 0.28);\n    border-radius: 10px;\n    padding: 12px 14px;\n    margin: 12px 0;\n    font-size: 0.87rem;\n}\n.sum-callout b { color: var(--primary-dark); }\n\n/* Table of contents — anchor links to each topic */\n.sum-toc {\n    background: #ffffff;\n    border: 1px solid #d4deee;\n    border-radius: 12px;\n    padding: 16px 18px;\n    margin: 14px 0 18px;\n}\n.sum-toc h3 {\n    color: #0f1e3d;\n    font-size: 1.02rem;\n    margin: 0 0 10px;\n    border: none;\n    padding: 0;\n}\n.sum-toc ol {\n    margin: 0;\n    padding: 0;\n    list-style: none;\n    display: grid;\n    grid-template-columns: repeat(auto-fill, minmax(min(100%, 220px), 1fr));\n    gap: 4px 18px;\n    counter-reset: toc;\n}\n.sum-toc li { margin: 0; font-size: 0.86rem; counter-increment: toc; }\n.sum-toc a {\n    display: flex;\n    gap: 8px;\n    align-items: baseline;\n    color: var(--primary-dark);\n    text-decoration: none;\n    padding: 5px 6px;\n    border-radius: 7px;\n    transition: background 0.15s ease;\n}\n.sum-toc a::before {\n    content: counter(toc);\n    font-weight: 800;\n    color: var(--text-light);\n    min-width: 20px;\n    font-size: 0.78rem;\n}\n.sum-toc a:hover { background: rgba(35, 109, 237, 0.08); }\n\n/* Management algorithm box — numbered decision flow */\n.sum-algo {\n    background: linear-gradient(180deg, rgba(35, 109, 237, 0.06), rgba(35, 109, 237, 0.02));\n    border: 1px solid rgba(35, 109, 237, 0.24);\n    border-inline-start: 4px solid #236ded;\n    border-radius: 10px;\n    padding: 12px 16px;\n    margin: 12px 0;\n    font-size: 0.87rem;\n}\n.sum-algo .sum-algo-title {\n    display: inline-flex;\n    align-items: center;\n    gap: 7px;\n    font-weight: 800;\n    color: var(--primary-dark);\n    font-size: 0.82rem;\n    letter-spacing: 0.3px;\n    margin-bottom: 6px;\n}\n.sum-algo .sum-algo-title::before { content: '⇢'; font-size: 1rem; }\n.sum-algo ol, .sum-algo ul { margin: 4px 0; padding-inline-start: 20px; }\n.sum-algo li { margin: 5px 0; }\n\n/* Exam key-points box — high-yield \"what they ask\" recall */\n.sum-key {\n    background: linear-gradient(180deg, rgba(16, 185, 129, 0.08), rgba(16, 185, 129, 0.02));\n    border: 1px solid rgba(16, 185, 129, 0.3);\n    border-inline-start: 4px solid #10b981;\n    border-radius: 10px;\n    padding: 12px 16px;\n    margin: 12px 0 4px;\n    font-size: 0.87rem;\n}\n.sum-key .sum-key-title {\n    display: inline-flex;\n    align-items: center;\n    gap: 7px;\n    font-weight: 800;\n    color: #047857;\n    font-size: 0.82rem;\n    letter-spacing: 0.3px;\n    margin-bottom: 6px;\n}\n.sum-key .sum-key-title::before { content: '★'; }\n.sum-key ul { margin: 4px 0; padding-inline-start: 20px; list-style: none; }\n.sum-key li { margin: 6px 0; padding-inline-start: 18px; position: relative; }\n.sum-key li::before {\n    content: '→';\n    position: absolute;\n    inset-inline-start: 0;\n    color: #10b981;\n    font-weight: 800;\n}\n.sum-key b { color: #047857; }\n\n/* Anchor offset so in-page TOC jumps aren't hidden under sticky headers */\n.sum-doc section.topic { scroll-margin-top: 80px; }\n\n/* Original anatomy / clinical diagrams (inline SVG) with a caption */\n.sum-fig {\n    margin: 14px 0;\n    padding: 14px;\n    background: #ffffff;\n    border: 1px solid #d4deee;\n    border-radius: 12px;\n    text-align: center;\n}\n.sum-fig svg {\n    width: 100%;\n    max-width: 460px;\n    height: auto;\n    display: block;\n    margin: 0 auto;\n}\n.sum-fig figcaption {\n    margin-top: 8px;\n    color: var(--text-light);\n    font-size: 0.8rem;\n    line-height: 1.5;\n}\n.sum-fig figcaption b { color: var(--primary-dark); }\n.sum-doc table { width: 100%; border-collapse: collapse; margin: 12px 0; font-size: 0.8rem; }\n.sum-doc th, .sum-doc td {\n    border: 1px solid #d4deee;\n    padding: 7px 9px;\n    text-align: left;\n    vertical-align: top;\n}\n.sum-doc thead th { background: #ffffff; color: #1e293b; }\n.sum-doc tbody tr:nth-child(even) { background: rgba(15, 23, 42, 0.04); }\n\n.summary-stat-value .unit { font-size: 0.9rem; color: #475569; font-weight: 600; }\n\n.summary-q-option.correct {\n    border-color: #d4deee;\n    background: rgba(16, 78, 185, 0.12);\n    color: #6e9ae7;\n    font-weight: 700;\n}\n\n/* Deterrent: hide the slide content when printing / print-to-PDF. */\n@media print {\n    .summary-stage,\n    .summary-page-img,\n    .slide { display: none !important; }\n}\n\n.slide {\n    position: relative;\n    max-width: 1000px;\n    margin: 0 auto;\n    min-height: 74vh;\n    background:\n        radial-gradient(1200px 400px at 100% -10%, rgba(35, 109, 237, 0.10), transparent 60%),\n        linear-gradient(160deg, #ffffff 0%, #ffffff 100%);\n    border: 1px solid #d4deee;\n    border-radius: 18px;\n    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.20);\n    overflow: hidden;\n}\n.slide-body.sum-doc { line-height: 1.75; }\n.slide-body.sum-doc li { font-size: 0.98rem; margin: 6px 0; }\n.slide-body.sum-doc h4 { font-size: 1.05rem; margin: 16px 0 7px; }\n.slide-body.sum-doc table { font-size: 0.88rem; }\n.slide-body.sum-doc .sum-callout { font-size: 0.95rem; }\n.slide-intro-body .sum-head h2 { font-size: 1.7rem; }\n.slide-intro-body .sum-meta { font-size: 0.92rem; }\n.stb-group { display: inline-flex; align-items: center; gap: 5px; }\n.stb-sep { width: 1px; height: 22px; background: #d4deee; }\n.stb-btn {\n    width: 36px; min-width: 36px; height: 36px;\n    display: grid; place-items: center;\n    background: #ffffff;\n    border: 1px solid #d4deee;\n    border-radius: 9px;\n    color: #475569;\n    cursor: pointer;\n    font-family: inherit;\n    padding: 0;\n}\n.stb-btn:hover:not(:disabled) { border-color: #3b82f6; }\n.stb-btn.on { background: #3b82f6; color: #ffffff; border-color: #3b82f6; }\n.stb-btn:disabled { opacity: 0.4; cursor: not-allowed; }\n.stb-color {\n    width: 24px; height: 24px;\n    border-radius: 50%;\n    border: 2px solid transparent;\n    cursor: pointer;\n    padding: 0;\n}\n.stb-color.on { border-color: #e6ecf7; box-shadow: 0 0 0 2px #3b82f6; }\n\n@media (max-width: 640px) {\n    .slide { min-height: 70vh; }\n}\n.toc-backdrop.show { opacity: 1; pointer-events: auto; }\n.summary-toc.open { transform: translateX(0); box-shadow: -18px 0 44px rgba(15, 23, 42, 0.22); }\n.toc-section-btn.active { background: rgba(35, 109, 237, 0.1); color: var(--primary-dark); }\n.toc-sub-btn.active { color: var(--primary-dark); font-weight: 700; background: rgba(35, 109, 237, 0.07); }\n\n/* Level 3a — summary content (rich .sum-doc) */\n.sub-summary { padding: 16px 22px 4px; line-height: 1.7; color: #1e293b; }\n/* #bcd2f5 is near-invisible on the panel's white background — the accent\n   diamond carries the colour, so the label itself reads in the body ink. */\n.sub-summary h4 { display: flex; align-items: center; gap: 9px; color: #0f1e3d; font-size: 1rem; font-weight: 800; margin: 18px 0 9px; }\n.sub-summary h4::before { content: ''; width: 8px; height: 8px; border-radius: 2px; background: var(--accent); transform: rotate(45deg); }\n.sub-summary ul { list-style: none; margin: 9px 0; padding: 0; }\n.sub-summary ul li { position: relative; padding-inline-start: 20px; margin: 8px 0; font-size: 0.92rem; line-height: 1.7; }\n.sub-summary ul li::before { content: ''; position: absolute; inset-inline-start: 3px; top: 0.62em; width: 6px; height: 6px; border-radius: 50%; background: var(--accent); opacity: 0.75; }\n.sub-summary ol { margin: 9px 0; padding-inline-start: 22px; }\n.sub-summary ol li { margin: 7px 0; font-size: 0.92rem; line-height: 1.7; }\n.sub-summary ol li::marker { color: var(--accent); font-weight: 800; }\n.sub-summary b { color: #0f1e3d; font-weight: 700; }\n\n.sub-summary table { width: 100%; border-collapse: separate; border-spacing: 0; margin: 16px 0; font-size: 0.83rem; border: 1px solid #d4deee; border-radius: 12px; overflow: hidden; }\n.sub-summary thead th { background: linear-gradient(180deg, #eef3fc, #e6edf9); color: #0f1e3d; font-weight: 800; padding: 10px 12px; text-align: left; }\n.sub-summary td { padding: 9px 12px; text-align: left; vertical-align: top; border-top: 1px solid #d4deee; }\n.sub-summary th + th, .sub-summary td + td { border-inline-start: 1px solid #d4deee; }\n.sub-summary tbody tr:nth-child(even) td { background: rgba(15, 23, 42, 0.04); }\n\n/* Wide medical tables scroll horizontally on narrow screens. A JS effect wraps\n   each <table> in `.table-scroll > .table-scroll-inner`; the inner div is the\n   scroll container and the non-scrolling outer anchors an edge shadow so the\n   horizontal scroll is discoverable. `.can-scroll` is toggled while more of the\n   table is off-screen. The wrappers are inert on desktop (no overflow, no shadow). */\n.sub-summary .table-scroll { position: relative; margin: 16px 0; }\n.sub-summary .table-scroll > .table-scroll-inner > table { margin: 0; }\n@media (max-width: 720px) {\n    .sub-summary .table-scroll-inner {\n        overflow-x: auto;\n        overflow-y: hidden;\n        -webkit-overflow-scrolling: touch;\n    }\n    .sub-summary .table-scroll-inner > table {\n        display: table;\n        width: max-content;\n        min-width: 100%;\n        white-space: nowrap;\n    }\n    .sub-summary .table-scroll::after {\n        content: '';\n        position: absolute;\n        top: 0; bottom: 0; inset-inline-end: 0;\n        width: 30px;\n        background: linear-gradient(to left, rgba(37, 99, 235, 0.20), transparent);\n        border-radius: 0 12px 12px 0;\n        pointer-events: none;\n        opacity: 0;\n        transition: opacity 0.2s ease;\n    }\n    .sub-summary .table-scroll.can-scroll::after { opacity: 1; }\n    /* fallback: any table not yet wrapped by JS still scrolls */\n    .sub-summary > table {\n        display: block;\n        overflow-x: auto;\n        overflow-y: hidden;\n        -webkit-overflow-scrolling: touch;\n        white-space: nowrap;\n    }\n}\n\n.sub-summary .sum-callout {\n    position: relative; margin: 16px 0; padding: 13px 15px;\n    background: linear-gradient(180deg, rgba(15, 23, 42, 0.04), rgba(15, 23, 42, 0.04));\n    border: 1px solid #d4deee; border-inline-start: 3px solid var(--accent); border-radius: 11px;\n    font-size: 0.88rem;\n}\n.sub-summary .sum-callout > b:first-child {\n    display: block; color: var(--accent); font-size: 0.74rem; font-weight: 800;\n    letter-spacing: 0.6px; text-transform: uppercase; margin-bottom: 7px;\n}\n.sub-summary .sum-callout ul { margin: 4px 0 0; }\n\n/* Level 3b — questions */\n.sub-questions { padding: 6px 22px 18px; }\n\n.sq-card { background: linear-gradient(180deg, #ffffff, #ffffff); border: 1px solid #d4deee; border-radius: 14px; padding: 16px 18px; margin-bottom: 12px; transition: border-color 0.15s ease; }\n.sq-card.is-revealed { border-color: #d4deee; }\n.sq-stem { display: flex; gap: 11px; color: #1e293b; font-weight: 600; font-size: 0.95rem; line-height: 1.65; margin: 0 0 14px; text-align: left; }\n.sq-num { flex: 0 0 auto; height: fit-content; background: rgba(35, 109, 237, 0.12); color: var(--primary-dark); font-weight: 800; font-size: 0.7rem; border-radius: 7px; padding: 3px 8px; }\n.sq-options { display: flex; flex-direction: column; gap: 8px; }\n.sq-option {\n    display: flex; align-items: center; gap: 12px; text-align: left;\n    border: 1px solid #d4deee; background: #ffffff; color: #1e293b;\n    border-radius: 11px; padding: 11px 14px; font-family: inherit; font-size: 0.9rem;\n    cursor: pointer; transition: transform 0.12s ease, border-color 0.12s ease, background 0.12s ease;\n}\n.sq-option:hover:not(:disabled) { border-color: var(--accent); background: #ffffff; transform: translateY(-1px); }\n.sq-option:disabled { cursor: default; }\n.sq-letter { flex: 0 0 auto; width: 26px; height: 26px; display: grid; place-items: center; border-radius: 50%; background: #ffffff; border: 1px solid #d4deee; color: #93a4bd; font-weight: 800; font-size: 0.78rem; }\n.sq-opt-text { flex: 1; }\n.sq-mark { margin-inline-start: auto; font-weight: 900; font-size: 0.95rem; }\n.sq-option.correct { border-color: #d4deee; background: rgba(16, 78, 185, 0.12); color: #1e293b; }\n.sq-option.correct .sq-letter { background: #104eb9; border-color: #d4deee; color: #ffffff; }\n.sq-option.wrong { border-color: #f43f5e; background: rgba(244, 63, 94, 0.1); color: #1e293b; }\n.sq-option.wrong .sq-letter { background: #f43f5e; border-color: #f43f5e; color: #ffffff; }\n.sq-explain { margin-top: 13px; padding: 12px 14px; background: rgba(35, 109, 237, 0.06); border: 1px solid rgba(35, 109, 237, 0.2); border-inline-start: 3px solid var(--accent); border-radius: 11px; color: #1e293b; font-size: 0.86rem; line-height: 1.6; text-align: left; animation: sq-reveal 0.25s ease; }\n.sq-explain b { color: #0f1e3d; }\n.sq-verdict { display: inline-flex; align-items: center; gap: 5px; }\n.sq-source { display: inline-block; margin-inline-start: 8px; color: #475569; font-size: 0.72rem; }\n@keyframes sq-reveal { from { opacity: 0; transform: translateY(-4px); } to { opacity: 1; transform: none; } }\n\n/* ── Study toolbar: a vertical rail docked to the side ────────────────────\n   It used to sit across the bottom centre, where it covered the last lines of\n   every page and sat right where a thumb rests while reading. Docked to the\n   left edge and vertically centred it stays reachable without ever crossing\n   the reading column, which is capped at 920px and centred. */\n.summary-fab {\n    position: fixed; left: 14px; top: 50%; transform: translateY(-50%);\n    display: flex; flex-direction: column; align-items: center; gap: 8px;\n    max-height: 90vh; overflow-y: auto;\n    background: rgba(255, 255, 255, 0.9); -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px);\n    border: 1px solid #d4deee; border-radius: 16px; padding: 12px 8px;\n    box-shadow: 0 18px 44px rgba(37, 99, 235, 0.16); z-index: 60;\n    animation: fab-pop 0.18s ease;\n}\n@keyframes fab-pop { from { opacity: 0; transform: translateY(-50%) translateX(-8px); } to { opacity: 1; transform: translateY(-50%) translateX(0); } }\n\n/* Groups and separators run down the rail instead of across it. */\n.summary-fab .stb-group { flex-direction: column; }\n.summary-fab .stb-sep { width: 22px; height: 1px; }\n\n/* collapsed trigger — a compact pill on the same edge as the open rail */\n.summary-fab-toggle {\n    position: fixed; left: 14px; top: 50%; transform: translateY(-50%);\n    display: inline-flex; flex-direction: column; align-items: center; gap: 4px;\n    width: 46px; padding: 12px 0;\n    background: rgba(255, 255, 255, 0.92); -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px);\n    border: 1px solid #d4deee; border-radius: 14px;\n    color: var(--accent); font-family: inherit; font-weight: 800; font-size: 0.58rem;\n    box-shadow: 0 12px 30px rgba(37, 99, 235, 0.18);\n    cursor: pointer; z-index: 60;\n    transition: transform 0.15s ease, box-shadow 0.15s ease, border-color 0.15s ease;\n}\n.summary-fab-toggle:hover { transform: translateY(-50%) translateX(2px); box-shadow: 0 16px 36px rgba(37, 99, 235, 0.26); border-color: var(--accent); }\n.summary-fab-toggle:active { transform: translateY(-50%) scale(0.97); }\n.summary-fab-toggle .label { letter-spacing: 0.2px; line-height: 1.15; text-align: center; }\n\n/* Narrow screens have no side gutter to spare: fall back to a horizontal bar\n   pinned to the bottom, which is the only place it doesn't steal read width. */\n@media (max-width: 720px) {\n    .summary-fab {\n        left: 50%; right: auto; top: auto; bottom: 14px;\n        transform: translateX(-50%);\n        flex-direction: row; flex-wrap: wrap; justify-content: center;\n        max-width: 94vw; max-height: none; padding: 8px 12px;\n    }\n    .summary-fab .stb-group { flex-direction: row; }\n    .summary-fab .stb-sep { width: 1px; height: 22px; }\n    @keyframes fab-pop { from { opacity: 0; transform: translateX(-50%) translateY(8px); } to { opacity: 1; transform: translateX(-50%) translateY(0); } }\n\n    .summary-fab-toggle {\n        left: 50%; top: auto; bottom: 14px;\n        transform: translateX(-50%);\n        flex-direction: row; width: auto; height: 44px; padding: 0 18px;\n        gap: 8px; border-radius: 999px; font-size: 0.85rem;\n    }\n    .summary-fab-toggle:hover { transform: translateX(-50%) translateY(-2px); }\n    .summary-fab-toggle:active { transform: translateX(-50%) scale(0.97); }\n}\n\n/* collapse (hide) button distinguishes itself on hover */\n.stb-collapse:hover:not(:disabled) { border-color: #f43f5e; color: #dc2626; }\n\n/* keyboard focus rings for every study control (a11y) */\n.summary-fab-toggle:focus-visible,\n.stb-btn:focus-visible,\n.stb-color:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }\n\n@media (max-width: 768px) {\n    .sub-head, .sub-summary, .sub-questions { padding-inline: 16px; }\n}\n\n@media print {\n    .summary-annotation-canvas, .summary-toc, .summary-fab, .summary-readbar, .toc-backdrop { display: none !important; }\n}\n\n/* ===================================================================== */\n/* ============ CARDS-IN-CARDS HUB + POPOUT PANEL (new) ================ */\n/* ===================================================================== */\n.summaries-hub {\n    --accent: #2563eb;\n    min-height: calc(100vh - 72px);\n    background:\n        radial-gradient(1100px 560px at 82% -8%, rgba(59, 130, 246, 0.08), transparent 55%),\n        radial-gradient(820px 460px at 6% 4%, rgba(16, 78, 185, 0.06), transparent 50%),\n        linear-gradient(180deg, #eef2fb 0%, #ffffff 60%);\n    color: #1e293b;\n    /* Direction follows the hub's dir attribute (the site language); the\n       authored English material carries its own dir=\"ltr\". */\n    padding: 30px clamp(14px, 4vw, 48px) 90px;\n    box-sizing: border-box;\n}\n\n/* ---- header: what the path leads to, and where the student is ---- */\n.hub-head {\n    position: relative; overflow: hidden;\n    max-width: var(--container-wide); margin: 0 auto 26px;\n    padding: clamp(20px, 3vw, 32px);\n    background: linear-gradient(152deg, #ffffff 0%, #f5f8ff 100%);\n    border: 1px solid #dde5f3; border-radius: 24px;\n    box-shadow: 0 18px 46px rgba(37, 99, 235, 0.10), 0 2px 8px rgba(15, 23, 42, 0.04);\n}\n.hub-head::before {\n    content: ''; position: absolute; inset-inline-end: -90px; top: -110px;\n    width: 300px; height: 300px; border-radius: 50%; pointer-events: none;\n    background: radial-gradient(circle, rgba(59, 130, 246, 0.16), transparent 68%);\n}\n.hub-eyebrow {\n    position: relative; display: inline-flex; align-items: center; gap: 7px;\n    font-size: 0.7rem; font-weight: 900; letter-spacing: 1.4px; text-transform: uppercase;\n    color: #2563eb; background: rgba(37, 99, 235, 0.10);\n    border: 1px solid rgba(37, 99, 235, 0.22); border-radius: 999px; padding: 5px 13px;\n}\n.hub-head h1 {\n    position: relative;\n    font-size: clamp(1.65rem, 4vw, 2.25rem); font-weight: 900; margin: 14px 0 10px; line-height: 1.18;\n    background: linear-gradient(92deg, #0f1e3d 10%, #3b82f6);\n    -webkit-background-clip: text; background-clip: text; color: transparent;\n}\n\n/* what the whole path contains */\n.hub-facts { position: relative; display: flex; flex-wrap: wrap; gap: 8px 10px; margin-top: 18px; }\n.hub-fact {\n    display: inline-flex; align-items: center; gap: 7px;\n    font-size: 0.8rem; font-weight: 700; color: #475569;\n    background: #ffffff; border: 1px solid #e2e8f5; border-radius: 999px; padding: 6px 13px;\n}\n.hub-fact b { color: #0f1e3d; font-size: 0.92rem; font-weight: 900; }\n.hub-fact svg { color: #2563eb; }\n\n/* position on the path: step X of Y · Z% */\n.hub-track { position: relative; margin-top: 22px; }\n.hub-track-top {\n    display: flex; align-items: center; flex-wrap: wrap; gap: 8px;\n    font-size: 0.84rem; font-weight: 700; color: #475569; margin-bottom: 9px;\n}\n.hub-track-pos { color: #0f1e3d; font-weight: 800; }\n.hub-track-pos b { font-size: 1.05rem; font-weight: 900; color: #2563eb; }\n.hub-track-sep { color: #93a4bd; }\n.hub-track-pct b { color: #0f1e3d; font-weight: 900; }\n.hub-track-done {\n    margin-inline-start: auto; display: inline-flex; align-items: center; gap: 5px;\n    font-size: 0.74rem; font-weight: 800; color: var(--secondary-dark);\n    background: rgba(22, 163, 74, 0.12); border-radius: 999px; padding: 4px 11px;\n}\n.hub-track-bar {\n    position: relative; height: 12px; border-radius: 999px; overflow: hidden;\n    background: #e2e8f5; box-shadow: inset 0 1px 3px rgba(15, 23, 42, 0.08);\n}\n.hub-track-fill {\n    height: 100%; border-radius: 999px; min-width: 0;\n    background: linear-gradient(90deg, #16a34a, #34d399);\n    box-shadow: 0 0 12px rgba(22, 163, 74, 0.45);\n    transition: width 0.5s cubic-bezier(0.4, 0, 0.2, 1);\n}\n.hub-track-tick {\n    position: absolute; top: 0; bottom: 0; width: 2px;\n    background: rgba(255, 255, 255, 0.85); transform: translateX(-1px);\n}\n.hub-track-legend { display: flex; flex-wrap: wrap; gap: 6px 8px; margin-top: 11px; }\n.hub-leg {\n    display: inline-flex; align-items: center; gap: 7px; cursor: pointer;\n    font-family: inherit; font-size: 0.74rem; font-weight: 700; color: #475569;\n    background: none; border: 1px solid transparent; border-radius: 999px; padding: 4px 10px 4px 6px;\n    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;\n}\n.hub-leg i { width: 9px; height: 9px; border-radius: 50%; background: var(--accent); flex: 0 0 auto; }\n.hub-leg b { color: #0f1e3d; font-weight: 900; }\n.hub-leg:hover { background: rgba(15, 23, 42, 0.04); border-color: #dde5f3; color: #0f1e3d; }\n.hub-leg.is-complete { color: var(--secondary-dark); }\n.hub-leg.is-complete i { background: #16a34a; box-shadow: 0 0 0 3px rgba(22, 163, 74, 0.18); }\n\n/* start / continue-where-you-left-off */\n.hub-resume {\n    position: relative; display: flex; align-items: center; flex-wrap: wrap; gap: 16px;\n    margin-top: 22px; padding: 18px 20px; border-radius: 18px;\n    background: linear-gradient(140deg, #eff5ff 0%, #ffffff 70%);\n    border: 1px solid rgba(37, 99, 235, 0.28);\n    box-shadow: 0 10px 28px rgba(37, 99, 235, 0.10);\n}\n.hub-resume.is-resuming { background: linear-gradient(140deg, #fff8ec 0%, #ffffff 70%); border-color: rgba(245, 158, 11, 0.4); }\n.hub-resume.is-finished { background: linear-gradient(140deg, #f0fdf4 0%, #ffffff 70%); border-color: rgba(22, 163, 74, 0.4); }\n.hub-resume-node {\n    flex: 0 0 auto; width: 46px; height: 46px; border-radius: 14px;\n    display: grid; place-items: center; color: #ffffff;\n    background: linear-gradient(160deg, #3b82f6, #2563eb);\n    box-shadow: 0 8px 18px rgba(37, 99, 235, 0.35);\n}\n.hub-resume.is-resuming .hub-resume-node { background: linear-gradient(160deg, #fbbf24, #f59e0b); box-shadow: 0 8px 18px rgba(245, 158, 11, 0.35); }\n.hub-resume.is-finished .hub-resume-node { background: linear-gradient(160deg, #22c55e, #16a34a); box-shadow: 0 8px 18px rgba(22, 163, 74, 0.35); }\n.hub-resume-text { flex: 1 1 260px; min-width: 0; display: flex; flex-direction: column; gap: 3px; }\n.hub-resume-kicker { font-size: 0.68rem; font-weight: 900; letter-spacing: 1.3px; text-transform: uppercase; color: #2563eb; }\n.hub-resume.is-resuming .hub-resume-kicker { color: #b45309; }\n.hub-resume.is-finished .hub-resume-kicker { color: var(--secondary-dark); }\n.hub-resume-title { font-size: 1.08rem; font-weight: 900; color: #0f1e3d; line-height: 1.3; }\n.hub-resume-why { font-size: 0.85rem; color: #475569; line-height: 1.6; }\n.hub-resume-meta { font-size: 0.73rem; font-weight: 700; color: #8494ab; margin-top: 2px; }\n.hub-resume-actions { flex: 0 0 auto; display: flex; flex-direction: column; align-items: stretch; gap: 6px; }\n.hub-resume-cta {\n    display: inline-flex; align-items: center; justify-content: center; gap: 6px;\n    padding: 12px 20px; border: none; border-radius: 12px; cursor: pointer;\n    font-family: inherit; font-size: 0.92rem; font-weight: 900; color: #ffffff;\n    background: linear-gradient(135deg, #3b82f6, #2563eb);\n    box-shadow: 0 8px 20px rgba(37, 99, 235, 0.34);\n    transition: transform 0.16s ease, box-shadow 0.16s ease, filter 0.16s ease;\n}\n.hub-resume-cta:hover { transform: translateY(-2px); box-shadow: 0 12px 26px rgba(37, 99, 235, 0.42); filter: brightness(1.05); }\n.hub-resume-cta:active { transform: translateY(0) scale(0.98); }\n.hub-resume-link {\n    background: none; border: none; cursor: pointer; font-family: inherit;\n    font-size: 0.76rem; font-weight: 700; color: var(--text-light); text-decoration: underline;\n    text-underline-offset: 3px; padding: 2px;\n}\n.hub-resume-link:hover { color: #2563eb; }\n\n/* topic search */\n.hub-search {\n    position: relative; display: flex; align-items: center;\n    margin-top: 20px; max-width: 520px;\n}\n.hub-search-icon { position: absolute; inset-inline-start: 14px; color: var(--text-light); pointer-events: none; }\n.hub-search-input {\n    width: 100%; box-sizing: border-box;\n    padding: 12px 42px 12px 44px;\n    background: #ffffff; border: 1px solid #d4deee; border-radius: 12px;\n    /* 16px — below that, iOS Safari zooms the page on focus. */\n    color: #0f1e3d; font-family: inherit; font-size: 16px;\n    box-shadow: 0 4px 14px rgba(15, 23, 42, 0.05);\n    transition: border-color 0.15s ease, box-shadow 0.15s ease;\n}\n.hub-search-input::placeholder { color: var(--text-light); }\n.hub-search-input:focus {\n    outline: none; border-color: #2563eb;\n    box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.15);\n}\n.hub-search-clear {\n    position: absolute; inset-inline-end: 10px;\n    width: 26px; height: 26px; display: grid; place-items: center;\n    border: none; border-radius: 50%; cursor: pointer;\n    background: rgba(15, 23, 42, 0.06); color: #475569; font-family: inherit;\n    transition: background 0.15s ease, color 0.15s ease;\n}\n.hub-search-clear:hover { background: rgba(220, 38, 38, 0.12); color: #dc2626; }\n\n/* no-results empty state */\n.hub-empty {\n    display: flex; flex-direction: column; align-items: center; gap: 12px;\n    padding: 60px 20px; text-align: center; color: var(--text-light);\n}\n.hub-empty svg { color: var(--text-light); }\n.hub-empty p { margin: 0; font-size: 1rem; font-weight: 600; color: #475569; }\n.hub-empty-clear {\n    border: 1px solid #d4deee; background: #fff; color: #2563eb;\n    border-radius: 10px; padding: 9px 18px; font-family: inherit;\n    font-weight: 800; font-size: 0.88rem; cursor: pointer;\n    transition: border-color 0.15s ease, background 0.15s ease;\n}\n.hub-empty-clear:hover { border-color: #2563eb; background: rgba(37, 99, 235, 0.06); }\n\n/* ===================================================================== */\n/* ---- THE LEARNING PATH: rail · milestones · steps · checkpoints ------ */\n/* ===================================================================== */\n/* Geometry note: every row is a 2-column grid (rail | content) and the rail\n   line spans the full row track, so spacing MUST come from margins on the\n   content column — padding on a row would leave gaps in the line. */\n.path {\n    --rail: 58px; --node: 32px;\n    list-style: none; max-width: var(--container-wide); margin: 0 auto; padding: 0;\n}\n.path-row { display: grid; grid-template-columns: var(--rail) minmax(0, 1fr); column-gap: 18px; }\n.path-rail { position: relative; display: flex; justify-content: center; }\n.path-rail::before {\n    content: ''; position: absolute; inset-block: 0; inset-inline-start: 50%;\n    width: 3px; margin-inline-start: -1.5px; border-radius: 3px;\n    background: #dde5f3; transition: background 0.4s ease;\n}\n.path-node {\n    position: relative; z-index: 1; flex: 0 0 auto; margin-top: 3px;\n    width: var(--node); height: var(--node); border-radius: 50%;\n    display: grid; place-items: center;\n    font-size: 0.76rem; font-weight: 900; font-variant-numeric: tabular-nums;\n    background: #ffffff; color: #93a4bd; border: 2px solid #dde5f3;\n    transition: background 0.25s ease, border-color 0.25s ease, color 0.25s ease, transform 0.25s ease, box-shadow 0.25s ease;\n}\n/* the line starts at the very first node, not above it */\n.path > .milestone:first-child .ms-head-row .path-rail::before { top: 24px; }\n\n/* ---- milestone ---- */\n.milestone { list-style: none; }\n.ms-head-row .path-rail { --node: 46px; }\n.ms-node {\n    width: 46px; height: 46px; font-size: 1rem;\n    border-color: color-mix(in srgb, var(--accent) 45%, #dde5f3);\n    color: var(--accent);\n    background: linear-gradient(160deg, #ffffff, color-mix(in srgb, var(--accent) 10%, #ffffff));\n}\n.milestone.is-current .ms-node {\n    color: #ffffff; border-color: transparent;\n    background: linear-gradient(160deg, color-mix(in srgb, var(--accent) 78%, #ffffff), var(--accent));\n    box-shadow: 0 6px 18px color-mix(in srgb, var(--accent) 45%, transparent);\n}\n.milestone.is-complete .ms-node { color: #ffffff; border-color: transparent; background: linear-gradient(160deg, #22c55e, #16a34a); box-shadow: 0 6px 18px rgba(22, 163, 74, 0.35); }\n.milestone.is-complete .path-rail::before { background: rgba(22, 163, 74, 0.42); }\n\n.ms-head {\n    display: flex; align-items: flex-start; gap: 18px; width: 100%;\n    margin-bottom: 14px; padding: 20px 22px;\n    background: linear-gradient(160deg, #ffffff 0%, #f7faff 100%);\n    border: 1px solid #dde5f3; border-radius: 20px;\n    box-shadow: 0 8px 26px rgba(37, 99, 235, 0.07);\n    font-family: inherit; text-align: left; color: inherit; cursor: pointer;\n    transition: border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;\n}\n.ms-head:hover { border-color: color-mix(in srgb, var(--accent) 55%, #dde5f3); box-shadow: 0 12px 32px rgba(37, 99, 235, 0.13); }\n.milestone.is-current > .ms-head-row .ms-head {\n    border-color: color-mix(in srgb, var(--accent) 55%, #dde5f3);\n    background: linear-gradient(160deg, #ffffff 0%, color-mix(in srgb, var(--accent) 7%, #ffffff) 100%);\n}\n.milestone.is-complete > .ms-head-row .ms-head { border-color: rgba(22, 163, 74, 0.34); background: linear-gradient(160deg, #ffffff 0%, #f4fbf6 100%); }\n\n.ms-head-main { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 5px; }\n.ms-kicker {\n    display: flex; align-items: center; flex-wrap: wrap; gap: 8px;\n    font-size: 0.68rem; font-weight: 900; letter-spacing: 1.2px; text-transform: uppercase; color: var(--accent);\n}\n.ms-here {\n    font-style: normal; letter-spacing: 0.6px; color: #ffffff;\n    background: var(--accent); border-radius: 999px; padding: 3px 9px;\n}\n.ms-title { display: flex; align-items: center; gap: 11px; font-size: 1.35rem; font-weight: 900; color: #0f1e3d; line-height: 1.2; }\n.ms-icon {\n    flex: 0 0 auto; width: 38px; height: 38px; display: grid; place-items: center;\n    border-radius: 12px; color: var(--accent);\n    background: color-mix(in srgb, var(--accent) 13%, transparent);\n    border: 1px solid color-mix(in srgb, var(--accent) 28%, transparent);\n}\n.ms-goal { font-size: 0.87rem; color: #475569; line-height: 1.65; max-width: var(--container-form); }\n.ms-meta { display: flex; flex-wrap: wrap; gap: 6px 16px; margin-top: 3px; font-size: 0.74rem; font-weight: 700; color: #8494ab; }\n.ms-meta span { display: inline-flex; align-items: center; gap: 5px; }\n.ms-meta svg { color: #93a4bd; }\n\n.ms-side { flex: 0 0 auto; display: flex; flex-direction: column; align-items: center; gap: 7px; }\n.ms-ring {\n    position: relative; width: 46px; height: 46px; border-radius: 50%;\n    display: grid; place-items: center;\n    background: conic-gradient(var(--accent) calc(var(--p) * 1%), #e2e8f5 0);\n    transition: background 0.5s ease;\n}\n.milestone.is-complete .ms-ring { background: conic-gradient(#16a34a 100%, #16a34a 0); }\n.ms-ring::before { content: ''; position: absolute; inset: 4px; border-radius: 50%; background: #ffffff; }\n.ms-ring i { position: relative; font-style: normal; font-size: 0.62rem; font-weight: 900; color: #0f1e3d; }\n.ms-count { font-size: 0.7rem; font-weight: 800; color: var(--text-light); white-space: nowrap; }\n.ms-chev { font-size: 1.05rem; color: #93a4bd; transition: transform 0.3s ease, color 0.2s ease; }\n.ms-chev.open { transform: rotate(180deg); color: var(--accent); }\n\n/* collapsible body — animates to its natural height */\n.ms-body { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 0.42s cubic-bezier(0.4, 0, 0.2, 1); }\n.ms-body.open { grid-template-rows: 1fr; }\n.ms-body-inner { overflow: hidden; min-height: 0; }\n.ms-steps { list-style: none; margin: 0; padding: 0; }\n\n/* ---- a single step ---- */\n.path-step .step-node { color: var(--text-light); }\n.path-step.is-done .path-rail::before { background: rgba(22, 163, 74, 0.42); }\n.path-step.is-done .step-node { background: linear-gradient(160deg, #22c55e, #16a34a); border-color: transparent; color: #ffffff; box-shadow: 0 4px 12px rgba(22, 163, 74, 0.32); }\n/* the line stops being \"walked\" at the current node */\n.path-step.is-current .path-rail::before { background: linear-gradient(180deg, rgba(22, 163, 74, 0.42) 0 19px, #dde5f3 19px); }\n.path-step.is-current .step-node {\n    color: #ffffff; border-color: transparent; transform: scale(1.12);\n    background: linear-gradient(160deg, color-mix(in srgb, var(--accent) 80%, #ffffff), var(--accent));\n    box-shadow: 0 0 0 5px color-mix(in srgb, var(--accent) 16%, transparent), 0 6px 16px color-mix(in srgb, var(--accent) 40%, transparent);\n}\n\n.step-card {\n    position: relative; overflow: hidden;\n    display: flex; align-items: center; flex-wrap: wrap; gap: 14px 18px;\n    margin-bottom: 14px; padding: 15px 18px;\n    background: #ffffff; border: 1px solid #e2e8f5; border-radius: 16px;\n    box-shadow: 0 3px 12px rgba(15, 23, 42, 0.04);\n    transition: border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease, transform 0.18s ease;\n}\n.step-card:hover { border-color: color-mix(in srgb, var(--accent) 55%, #dde5f3); box-shadow: 0 10px 26px rgba(37, 99, 235, 0.13); transform: translateY(-2px); }\n.step-main { flex: 1 1 320px; min-width: 0; display: flex; flex-direction: column; gap: 5px; }\n\n.step-tags { display: flex; align-items: center; flex-wrap: wrap; gap: 7px; }\n.step-no { font-size: 0.68rem; font-weight: 900; letter-spacing: 1.1px; text-transform: uppercase; color: #93a4bd; }\n.step-state {\n    display: inline-flex; align-items: center; gap: 4px;\n    font-size: 0.64rem; font-weight: 900; letter-spacing: 0.7px; text-transform: uppercase;\n    border-radius: 999px; padding: 3px 9px;\n}\n.step-state.is-done { color: var(--secondary-dark); background: rgba(22, 163, 74, 0.13); }\n.step-state.is-current { color: #ffffff; background: var(--accent); box-shadow: 0 3px 10px color-mix(in srgb, var(--accent) 40%, transparent); }\n.step-state.is-upcoming { color: #8494ab; background: rgba(15, 23, 42, 0.05); }\n.step-state.is-resume { color: #b45309; background: rgba(245, 158, 11, 0.16); }\n\n.step-title { font-size: 1.02rem; font-weight: 800; color: #0f1e3d; margin: 0; line-height: 1.35; }\n.step-why { font-size: 0.85rem; color: #475569; margin: 0; line-height: 1.6; }\n.step-covers { font-size: 0.76rem; color: var(--text-light); margin: 2px 0 0; line-height: 1.5; }\n.step-covers-label {\n    display: inline-block; margin-inline-end: 6px;\n    font-size: 0.62rem; font-weight: 900; letter-spacing: 0.8px; text-transform: uppercase; color: var(--accent);\n}\n.step-meta { display: flex; flex-wrap: wrap; gap: 5px 14px; margin-top: 5px; font-size: 0.72rem; font-weight: 700; color: #8494ab; }\n.step-meta span { display: inline-flex; align-items: center; gap: 5px; }\n.step-meta svg { color: #93a4bd; }\n\n.step-actions { flex: 0 0 auto; display: flex; flex-direction: column; gap: 7px; min-width: 130px; }\n.step-cta {\n    display: inline-flex; align-items: center; justify-content: center; gap: 5px;\n    padding: 10px 16px; border-radius: 11px; cursor: pointer; font-family: inherit;\n    font-size: 0.84rem; font-weight: 800;\n    color: var(--accent); background: color-mix(in srgb, var(--accent) 10%, #ffffff);\n    border: 1px solid color-mix(in srgb, var(--accent) 32%, transparent);\n    transition: background 0.16s ease, color 0.16s ease, transform 0.16s ease, box-shadow 0.16s ease;\n}\n.step-cta:hover { background: var(--accent); color: #ffffff; box-shadow: 0 8px 18px color-mix(in srgb, var(--accent) 38%, transparent); }\n.step-cta:active { transform: scale(0.97); }\n.step-tick {\n    display: inline-flex; align-items: center; justify-content: center; gap: 5px;\n    padding: 7px 12px; border-radius: 10px; cursor: pointer; font-family: inherit;\n    font-size: 0.72rem; font-weight: 800; color: var(--text-light);\n    background: none; border: 1px solid #e2e8f5;\n    transition: color 0.15s ease, border-color 0.15s ease, background 0.15s ease, transform 0.12s ease;\n}\n.step-tick:hover { color: var(--secondary-dark); border-color: rgba(22, 163, 74, 0.5); background: rgba(22, 163, 74, 0.08); }\n.step-tick:active { transform: scale(0.96); }\n.step-tick.on { color: #ffffff; background: #16a34a; border-color: #16a34a; }\n.step-tick.on:hover { background: #15803d; border-color: #15803d; color: #ffffff; }\n\n/* completed step — green, calm, still fully readable */\n.path-step.is-done .step-card { background: linear-gradient(160deg, #f6fcf8 0%, #ffffff 65%); border-color: rgba(22, 163, 74, 0.28); }\n.path-step.is-done .step-card:hover { border-color: rgba(22, 163, 74, 0.55); box-shadow: 0 10px 26px rgba(22, 163, 74, 0.15); }\n.path-step.is-done .step-title { color: #14532d; }\n\n/* current step — the one thing that should catch the eye */\n.path-step.is-current .step-card {\n    padding: 19px 20px;\n    border-color: color-mix(in srgb, var(--accent) 60%, #dde5f3);\n    background: linear-gradient(150deg, color-mix(in srgb, var(--accent) 7%, #ffffff) 0%, #ffffff 62%);\n    box-shadow: 0 14px 34px color-mix(in srgb, var(--accent) 20%, transparent);\n}\n.path-step.is-current .step-title { font-size: 1.14rem; }\n.path-step.is-current .step-cta { background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 88%, #ffffff), var(--accent)); color: #ffffff; border-color: transparent; padding: 12px 20px; font-size: 0.9rem; box-shadow: 0 8px 20px color-mix(in srgb, var(--accent) 38%, transparent); }\n.path-step.is-current .step-cta:hover { filter: brightness(1.06); transform: translateY(-1px); }\n\n/* upcoming step — dimmed so order reads at a glance, never blocked */\n.path-step.is-upcoming .step-card { background: #fbfcff; border-color: #e9eef8; box-shadow: none; }\n.path-step.is-upcoming .step-title { color: #47566d; }\n.path-step.is-upcoming .step-why { color: #8494ab; }\n.path-step.is-upcoming .step-card:hover { background: #ffffff; box-shadow: 0 10px 26px rgba(37, 99, 235, 0.12); }\n\n/* the step the student walked away from */\n.path-step.is-resume .step-card { border-color: rgba(245, 158, 11, 0.5); background: linear-gradient(150deg, #fffaf0 0%, #ffffff 62%); }\n\n/* completing a step: node pops, a green sweep crosses the card */\n@keyframes step-node-pop { 0% { transform: scale(0.55); } 55% { transform: scale(1.3); } 100% { transform: scale(1); } }\n@keyframes step-sweep { from { transform: translateX(-100%); } to { transform: translateX(100%); } }\n@keyframes step-settle { 0% { transform: scale(1); } 30% { transform: scale(1.015); } 100% { transform: scale(1); } }\n.path-step.is-celebrating .step-node { animation: step-node-pop 0.6s cubic-bezier(0.34, 1.56, 0.64, 1); }\n.path-step.is-celebrating .step-card { animation: step-settle 0.6s ease; }\n.path-step.is-celebrating .step-card::after {\n    content: ''; position: absolute; inset: 0; pointer-events: none;\n    background: linear-gradient(100deg, transparent, rgba(22, 163, 74, 0.22), transparent);\n    animation: step-sweep 0.95s ease-out;\n}\n\n/* ---- checkpoint that closes a milestone ---- */\n.checkpoint-row .path-rail { --node: 36px; }\n.cp-node {\n    width: 36px; height: 36px; border-radius: 11px; transform: rotate(45deg);\n    color: #b45309; border-color: rgba(245, 158, 11, 0.55);\n    background: linear-gradient(160deg, #fffbf2, #fef3c7);\n}\n.cp-node svg { transform: rotate(-45deg); }\n.checkpoint-row.is-passed .cp-node { color: #ffffff; border-color: transparent; background: linear-gradient(160deg, #22c55e, #16a34a); box-shadow: 0 5px 14px rgba(22, 163, 74, 0.35); }\n.checkpoint-row.is-passed .path-rail::before { background: rgba(22, 163, 74, 0.42); }\n\n.checkpoint-card {\n    position: relative; margin-bottom: 30px; padding: 20px 22px;\n    background: linear-gradient(160deg, #fffcf3 0%, #ffffff 62%);\n    border: 1.5px dashed rgba(245, 158, 11, 0.5); border-radius: 20px;\n    transition: border-color 0.3s ease, background 0.3s ease;\n}\n.checkpoint-row.is-passed .checkpoint-card { border-style: solid; border-color: rgba(22, 163, 74, 0.4); background: linear-gradient(160deg, #f3fbf6 0%, #ffffff 62%); }\n@keyframes cp-flash { 0% { box-shadow: 0 0 0 0 rgba(22, 163, 74, 0.45); } 100% { box-shadow: 0 0 0 20px rgba(22, 163, 74, 0); } }\n.checkpoint-row.is-passing .checkpoint-card { animation: cp-flash 0.9s ease-out; }\n.checkpoint-row.is-passing .cp-node { animation: step-node-pop 0.65s cubic-bezier(0.34, 1.56, 0.64, 1); }\n\n.cp-head { display: flex; flex-direction: column; gap: 6px; }\n.cp-kicker {\n    align-self: flex-start; display: inline-flex; align-items: center; gap: 6px;\n    font-size: 0.66rem; font-weight: 900; letter-spacing: 1.3px; text-transform: uppercase;\n    color: #b45309; background: rgba(245, 158, 11, 0.15); border-radius: 999px; padding: 4px 11px;\n}\n.checkpoint-row.is-passed .cp-kicker { color: var(--secondary-dark); background: rgba(22, 163, 74, 0.14); }\n.cp-title { font-size: 1.12rem; font-weight: 900; color: #0f1e3d; margin: 0; line-height: 1.3; }\n.cp-recap { font-size: 0.86rem; color: #475569; margin: 0; line-height: 1.7; max-width: 640px; }\n.cp-recap b { color: #0f1e3d; }\n\n.cp-quiz { margin-top: 16px; padding-top: 14px; border-top: 1px solid rgba(15, 23, 42, 0.07); }\n.cp-prompt { font-size: 0.8rem; color: var(--text-light); margin: 0 0 12px; line-height: 1.65; }\n.cp-q { margin-bottom: 12px; }\n.cp-q-from { display: block; font-size: 0.63rem; font-weight: 900; letter-spacing: 0.8px; text-transform: uppercase; color: #93a4bd; margin-bottom: 5px; }\n.cp-question-card { margin-bottom: 0; background: #ffffff; }\n\n.cp-foot { display: flex; align-items: center; flex-wrap: wrap; gap: 12px; margin-top: 16px; }\n.cp-score { display: inline-flex; align-items: center; gap: 6px; font-size: 0.78rem; font-weight: 800; color: #8494ab; }\n.cp-score.is-complete { color: var(--secondary-dark); }\n.cp-pass {\n    margin-inline-start: auto; display: inline-flex; align-items: center; gap: 6px;\n    padding: 12px 20px; border: none; border-radius: 12px; cursor: pointer; font-family: inherit;\n    font-size: 0.86rem; font-weight: 900; color: #ffffff;\n    background: linear-gradient(135deg, #22c55e, #16a34a);\n    box-shadow: 0 8px 20px rgba(22, 163, 74, 0.32);\n    transition: transform 0.16s ease, box-shadow 0.16s ease, filter 0.16s ease;\n}\n.cp-pass:hover { transform: translateY(-2px); filter: brightness(1.05); box-shadow: 0 12px 26px rgba(22, 163, 74, 0.4); }\n.cp-pass:active { transform: translateY(0) scale(0.98); }\n.cp-redo {\n    margin-inline-start: auto; display: inline-flex; align-items: center; gap: 6px;\n    padding: 9px 15px; border-radius: 11px; cursor: pointer; font-family: inherit;\n    font-size: 0.78rem; font-weight: 800; color: #475569;\n    background: #ffffff; border: 1px solid #dde5f3;\n    transition: border-color 0.15s ease, color 0.15s ease;\n}\n.cp-redo:hover { border-color: #16a34a; color: var(--secondary-dark); }\n\n/* ---- the finish line ---- */\n.path-end { list-style: none; }\n.path-end .path-rail::before { inset-block: 0 auto; height: 22px; }\n.end-node { width: 42px; height: 42px; color: #93a4bd; background: #ffffff; }\n.path-end.is-reached .end-node { color: #ffffff; border-color: transparent; background: linear-gradient(160deg, #fbbf24, #f59e0b); box-shadow: 0 8px 22px rgba(245, 158, 11, 0.4); }\n.end-card { padding: 18px 22px 4px; }\n.end-card h3 { font-size: 1.05rem; font-weight: 900; color: #0f1e3d; margin: 0 0 5px; }\n.end-card p { font-size: 0.85rem; color: var(--text-light); margin: 0; line-height: 1.7; max-width: var(--container-form); }\n\n/* ---- search results (flat list, bypasses the path) ---- */\n.path-search { max-width: var(--container-wide); margin: 0 auto; }\n.path-search-head {\n    display: flex; align-items: center; flex-wrap: wrap; gap: 12px;\n    font-size: 0.84rem; font-weight: 800; color: #475569; margin: 0 0 14px;\n}\n.path-search-back {\n    margin-inline-start: auto; display: inline-flex; align-items: center; gap: 5px;\n    background: none; border: 1px solid #dde5f3; border-radius: 10px; cursor: pointer;\n    font-family: inherit; font-size: 0.76rem; font-weight: 800; color: var(--text-light); padding: 7px 13px;\n    transition: border-color 0.15s ease, color 0.15s ease;\n}\n.path-search-back:hover { border-color: #2563eb; color: #2563eb; }\n.path-search-list { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 10px; }\n.search-step {\n    display: flex; align-items: center; gap: 14px; width: 100%;\n    padding: 13px 16px; cursor: pointer; font-family: inherit; text-align: left;\n    background: #ffffff; border: 1px solid #e2e8f5; border-radius: 14px;\n    transition: border-color 0.16s ease, box-shadow 0.16s ease, transform 0.16s ease;\n}\n.search-step:hover { border-color: var(--accent); box-shadow: 0 8px 22px rgba(37, 99, 235, 0.13); transform: translateY(-2px); }\n.search-step-node {\n    flex: 0 0 auto; width: 30px; height: 30px; border-radius: 50%;\n    display: grid; place-items: center; font-size: 0.72rem; font-weight: 900;\n    color: var(--accent); background: color-mix(in srgb, var(--accent) 12%, transparent);\n    border: 1px solid color-mix(in srgb, var(--accent) 30%, transparent);\n}\n.search-step.is-done .search-step-node { color: #ffffff; background: #16a34a; border-color: #16a34a; }\n.search-step-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 2px; }\n.search-step-title { font-size: 0.95rem; font-weight: 800; color: #0f1e3d; }\n.search-step-covers { font-size: 0.74rem; color: #8494ab; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }\n.search-step-spec {\n    flex: 0 0 auto; display: inline-flex; align-items: center; gap: 5px;\n    font-size: 0.72rem; font-weight: 800; color: var(--accent);\n    background: color-mix(in srgb, var(--accent) 10%, transparent); border-radius: 999px; padding: 4px 11px;\n}\n.search-step-chev { flex: 0 0 auto; color: #93a4bd; }\n\n/* ---- Level 3: full-screen study modal ---- */\n/* Full-screen focused study modal — one topic at a time, centred content */\n.summary-panel {\n    --accent: #2563eb;\n    position: fixed; inset: 0; z-index: var(--z-modal);\n    display: flex; flex-direction: column;\n    background: linear-gradient(180deg, #ffffff 0%, #eef2fb 100%);\n    animation: panel-fade-in 0.24s ease;\n}\n@keyframes panel-fade-in { from { opacity: 0; transform: scale(0.985); } to { opacity: 1; transform: none; } }\n.summary-panel:fullscreen { background: linear-gradient(180deg, #ffffff 0%, #eef2fb 100%); }\n\n.panel-head {\n    display: flex; align-items: flex-start; gap: 12px; flex: 0 0 auto;\n    padding: 20px max(22px, calc((100% - 920px) / 2)) 16px;\n    border-bottom: 1px solid #d4deee;\n    background: linear-gradient(90deg, rgba(15, 23, 42, 0.04), transparent);\n}\n.panel-head-text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 4px; }\n.panel-spec { display: inline-flex; align-items: center; gap: 7px; font-size: 0.78rem; font-weight: 800; color: var(--accent); }\n.panel-title { font-size: 1.3rem; font-weight: 900; color: #0f1e3d; margin: 0; line-height: 1.25; }\n.panel-title-en { font-size: 0.72rem; color: #475569; letter-spacing: 0.5px; text-transform: uppercase; }\n.panel-close {\n    flex: 0 0 auto; width: 36px; height: 36px; border-radius: 10px;\n    display: grid; place-items: center;\n    background: rgba(15, 23, 42, 0.04); border: 1px solid #d4deee; color: #475569;\n    cursor: pointer; font-family: inherit;\n    transition: background 0.15s ease, color 0.15s ease, transform 0.15s ease;\n}\n.panel-close:hover { background: rgba(220, 38, 38, 0.12); color: #dc2626; transform: rotate(90deg); }\n\n/* \"Mark as done\" toggle — sits at the right end of the tabs row */\n.panel-done-btn {\n    flex: 0 0 auto; align-self: center; margin-inline-start: auto; margin-bottom: 6px;\n    display: inline-flex; align-items: center; gap: 7px;\n    height: 34px; padding: 0 14px; border-radius: 10px;\n    font-family: inherit; font-size: 0.82rem; font-weight: 800; cursor: pointer;\n    background: rgba(15, 23, 42, 0.04); border: 1px solid #d4deee; color: #475569;\n    transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.12s ease;\n}\n.panel-done-btn:hover { border-color: #16a34a; color: var(--secondary-dark); background: rgba(22, 163, 74, 0.10); }\n.panel-done-btn:active { transform: scale(0.96); }\n.panel-done-btn.on { background: #16a34a; border-color: #16a34a; color: #fff; }\n.panel-done-btn.on:hover { background: #15803d; border-color: #15803d; color: #fff; }\n@media (max-width: 640px) {\n    .panel-done-btn { padding: 0 10px; }\n    .panel-done-btn span.label { display: none; }\n}\n\n.panel-tabs { display: flex; gap: 4px; flex: 0 0 auto; padding: 12px max(22px, calc((100% - 920px) / 2)) 0; border-bottom: 1px solid #d4deee; }\n.panel-tab {\n    border: none; background: none; color: #93a4bd; font-family: inherit;\n    font-weight: 800; font-size: 0.9rem; padding: 10px 16px; cursor: pointer;\n    border-bottom: 2px solid transparent; transition: color 0.15s ease, border-color 0.15s ease;\n    display: inline-flex; align-items: center; gap: 7px;\n}\n.panel-tab:hover { color: #1e293b; }\n.panel-tab.active { color: var(--accent); border-bottom-color: var(--accent); }\n.panel-tab-badge {\n    font-size: 0.68rem; font-weight: 800; color: var(--accent);\n    background: rgba(59, 130, 246, 0.14); border-radius: 999px; padding: 2px 8px;\n}\n\n.panel-body { position: relative; flex: 1 1 auto; overflow-y: auto; padding: 26px max(22px, calc((100% - 920px) / 2)) 120px; }\n.panel-body::-webkit-scrollbar { width: 8px; }\n.panel-body::-webkit-scrollbar-thumb { background: #ffffff; border-radius: 8px; }\n/* centred reading column */\n.panel-inner { position: relative; z-index: 1; max-width: 920px; margin: 0 auto; width: 100%; }\n/* reuse existing .sub-summary + .sq-card styling inside the panel */\n.panel-body .sub-summary { padding: 0; }\n.panel-body .sub-questions { padding: 0; }\n/* drawing overlay — sized to scroll content, sits above the reading column */\n.panel-canvas { position: absolute; top: 0; left: 0; z-index: 6; }\n\n/* step position shown next to the specialty in the study modal */\n.panel-step {\n    font-style: normal; margin-inline-start: 4px;\n    font-size: 0.68rem; font-weight: 800; letter-spacing: 0.6px; color: var(--text-light);\n    background: rgba(15, 23, 42, 0.05); border-radius: 999px; padding: 3px 9px;\n}\n\n/* ---- path: narrow screens (the line still reads top-to-bottom) ---- */\n@media (max-width: 860px) {\n    .path { --rail: 46px; --node: 30px; }\n    .path-row { column-gap: 14px; }\n    .ms-head-row .path-rail { --node: 40px; }\n    .ms-node { width: 40px; height: 40px; font-size: 0.9rem; }\n    .path > .milestone:first-child .ms-head-row .path-rail::before { top: 21px; }\n    .path-step.is-current .path-rail::before { background: linear-gradient(180deg, rgba(22, 163, 74, 0.42) 0 18px, #dde5f3 18px); }\n\n    .ms-head { flex-wrap: wrap; gap: 12px; padding: 16px 17px; }\n    .ms-head-main { flex: 1 1 100%; }\n    .ms-side { flex: 1 1 100%; flex-direction: row; align-items: center; gap: 11px; }\n    .ms-chev { margin-inline-start: auto; }\n    .ms-title { font-size: 1.15rem; }\n    .ms-icon { width: 34px; height: 34px; }\n\n    .step-main { flex: 1 1 100%; }\n    .step-actions { flex: 1 1 100%; flex-direction: row; align-items: center; min-width: 0; }\n    .step-cta { flex: 1 1 auto; }\n    .step-tick { flex: 0 0 auto; }\n\n    .checkpoint-row .path-rail { --node: 32px; }\n    .cp-node { width: 32px; height: 32px; border-radius: 10px; }\n    .cp-pass, .cp-redo { flex: 1 1 100%; margin-inline-start: 0; justify-content: center; }\n\n    .end-node { width: 36px; height: 36px; }\n    .end-card { padding: 14px 0 4px; }\n\n    .hub-resume-actions { flex: 1 1 100%; }\n    .hub-resume-cta { width: 100%; }\n    .hub-resume-link { text-align: center; }\n}\n\n@media (max-width: 768px) {\n    .summaries-hub { min-height: calc(100vh - 56px); }\n}\n\n@media (max-width: 480px) {\n    .path { --rail: 38px; --node: 26px; }\n    .path-row { column-gap: 11px; }\n    .ms-head-row .path-rail { --node: 34px; }\n    .ms-node { width: 34px; height: 34px; font-size: 0.82rem; }\n    .path > .milestone:first-child .ms-head-row .path-rail::before { top: 18px; }\n    .path-step.is-current .path-rail::before { background: linear-gradient(180deg, rgba(22, 163, 74, 0.42) 0 16px, #dde5f3 16px); }\n    .path-node { margin-top: 2px; }\n    .ms-ring { width: 40px; height: 40px; }\n    .ms-goal { font-size: 0.83rem; }\n    .step-card, .path-step.is-current .step-card { padding: 14px 15px; }\n    .step-title { font-size: 0.97rem; }\n    .path-step.is-current .step-title { font-size: 1.05rem; }\n    .step-why { font-size: 0.82rem; line-height: 1.55; }\n    .step-covers { font-size: 0.73rem; }\n    .step-meta { gap: 4px 12px; font-size: 0.69rem; }\n    .checkpoint-card { padding: 17px 16px; }\n    .search-step-spec { display: none; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n    .ms-chev, .ms-body, .step-card, .step-node, .path-node, .path-rail::before,\n    .hub-track-fill, .ms-ring, .summary-panel, .panel-close, .search-step, .checkpoint-card {\n        transition: none !important; animation: none !important;\n    }\n    .path-step.is-celebrating .step-card::after { display: none; }\n}\n\n/* ===================================================================== */\n/* Study-deck enrichment — comparison tables · animated algorithms ·      */\n/* colour-coded clinical / diagnosis / management pearls.                 */\n/* ===================================================================== */\n.deck-enrich { position: relative; }\n.deck-enrich > h3 { color: #0b7285; border-bottom-color: #bfe6df; }\n.deck-enrich > h3::before { content: \"\\1F4D8\"; margin-inline-end: 7px; }\n.deck-intro { color: var(--text-light); font-size: 0.83rem; margin: -4px 0 14px; }\n\n/* per-topic clinical / diagnosis / management cards */\n.deck-topic { color: #0f1e3d; font-size: 1rem; font-weight: 700; margin: 18px 0 8px; padding-top: 4px; }\n.deck-cards { display: grid; grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); gap: 10px; margin: 8px 0; }\n.deck-card { border: 1px solid #e2e8f0; border-radius: 12px; padding: 10px 13px; background: #fbfdff; }\n.deck-card-h { display: inline-block; font-size: 0.68rem; font-weight: 800; letter-spacing: .04em; text-transform: uppercase; margin-bottom: 5px; padding: 2px 9px; border-radius: 999px; }\n.deck-card.clin { border-color: #bfe6df; } .deck-card.clin .deck-card-h { color: #0b7285; background: #e6f6f3; }\n.deck-card.diag { border-color: #c7d9f5; } .deck-card.diag .deck-card-h { color: #1d4ed8; background: #e8f0fe; }\n.deck-card.mgmt { border-color: #bfe3cd; } .deck-card.mgmt .deck-card-h { color: var(--secondary-dark); background: #e7f7ee; }\n.deck-card ul { margin: 2px 0 0; padding-inline-start: 18px; }\n.deck-card li { font-size: 0.85rem; margin: 3px 0; color: #1e293b; }\n.deck-card ul.sub { margin: 3px 0 5px; padding-inline-start: 16px; list-style: circle; }\n.deck-card ul.sub li { font-size: 0.81rem; margin: 2px 0; color: #475569; }\n\n/* blocks: tables & notes */\n.deck-block { margin: 15px 0; }\n.deck-cap { font-weight: 700; color: #0f1e3d; font-size: 0.94rem; margin-bottom: 6px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n.deck-subcap { color: var(--text-light); font-size: 0.8rem; font-style: italic; margin: -2px 0 8px; }\n.deck-tag { font-size: 0.63rem; font-weight: 800; text-transform: uppercase; letter-spacing: .05em; padding: 3px 9px; border-radius: 999px; }\n.tag-tbl { color: #1d4ed8; background: #e8f0fe; } .tag-algo { color: #0b7285; background: #e6f6f3; } .tag-fig { color: #7c3aed; background: #f3e8ff; }\n\n/* native clarification diagrams (inline SVG) */\n.deck-fig { margin: 16px 0; padding: 14px 12px 10px; border: 1px solid #d9d0f2; border-radius: 14px; background: linear-gradient(180deg, #fbfaff, #f6f3fe); text-align: center; }\n.deck-fig-title { font-weight: 700; color: #0f1e3d; font-size: 0.94rem; margin: 0 0 10px; display: flex; gap: 8px; align-items: center; justify-content: center; flex-wrap: wrap; }\n.deck-fig svg { max-width: 100%; height: auto; display: block; margin: 0 auto; }\n.deck-fig figcaption { font-size: 0.82rem; color: #475569; margin-top: 9px; line-height: 1.5; }\n.deck-fig figcaption b { color: #334155; }\n\n/* Raster figures/photos inside summaries — public (/summaries/…) or gated\n   (<img data-figure-key>) tiers both use .deck-img. */\n.deck-img { max-width: 100%; height: auto; display: block; margin: 8px auto 0; border-radius: 10px; }\n.deck-img.deck-img-loading { min-height: 120px; background: repeating-linear-gradient(90deg, #f1eefb, #f1eefb 12px, #e8e2f7 12px, #e8e2f7 24px); }\n.deck-img.deck-img-error { min-height: 60px; background: #fdecec; }\n\n/* Side-by-side illustration pairs (e.g. previa vs abruption). Stacks on narrow\n   screens so neither image drops below a legible size. */\n.deck-imgrow { display: grid; grid-template-columns: 1fr; gap: 14px; margin-top: 6px; }\n@media (min-width: 640px) { .deck-imgrow { grid-template-columns: 1fr 1fr; align-items: start; } }\n.deck-imgcell { display: flex; flex-direction: column; }\n.deck-imgcell .deck-img { margin-top: 0; border: 1px solid #e6e0f7; background: #fff; }\n.deck-imgcap { margin: 8px 0 0; font-size: 0.82rem; line-height: 1.6; color: #475569; }\n.deck-imgcap b { color: #0f1e3d; }\n.deck-hi { display: inline-block; margin-top: 5px; padding: 2px 9px; border-radius: 999px; font-size: 0.75rem; font-weight: 700; }\n.deck-hi--red { background: #fee2e2; color: #b91c1c; }\n.deck-hi--amber { background: #fef3c7; color: #92400e; }\n.deck-hi--green { background: #dcfce7; color: var(--secondary-dark); }\n.deck-hi--blue { background: #dbeafe; color: #1d4ed8; }\n\n/* Radiology/microscopy pairs: source images have wildly different aspect ratios\n   (a 426x429 AP neck next to a 400x628 lateral), so lock a common display\n   height and letterbox — otherwise one panel dwarfs the other. */\n.deck-imgrow--scan .deck-img { height: 240px; width: auto; max-width: 100%; object-fit: contain; margin-inline: auto; background: #0b1220; }\n@media (max-width: 639px) { .deck-imgrow--scan .deck-img { height: 200px; } }\n\n/* Warning strip under a figure (e.g. do-not-examine-the-throat). */\n.deck-warn { margin: 12px 0 0; padding: 9px 12px; border-radius: 9px; background: #fef3c7; border: 1px solid #f59e0b; color: #92400e; font-size: 0.8rem; font-weight: 700; line-height: 1.55; }\n\n/* Attribution line for open-licensed imagery. REQUIRED by CC BY — removing it\n   breaks the licence terms. Keep it with the image it credits. */\n.deck-credit { margin: 10px 0 0; font-size: 0.7rem; line-height: 1.6; color: var(--text-light); }\n.deck-credit a { color: var(--text-light); text-decoration: underline; }\n.deck-tbl-notes { margin: 8px 0 0; padding-inline-start: 20px; } .deck-tbl-notes li { font-size: 0.83rem; margin: 3px 0; color: #334155; }\n.deck-notelist ul.sub { margin: 2px 0 4px; padding-inline-start: 18px; } .deck-notelist ul.sub li { font-size: 0.83rem; color: #475569; margin: 2px 0; }\n\n/* animated algorithm flow */\n.algo-flow { margin: 16px 0; padding: 14px 14px 16px; border: 1px solid #d4e3ee; border-radius: 14px; background: linear-gradient(180deg, #f8fbfe, #f2f7fb); }\n.algo-flow figcaption { font-weight: 700; color: #0f1e3d; font-size: 0.94rem; margin: 0 0 10px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n.algo-flow .deck-subcap { text-align: center; }\n.algo-row { display: flex; justify-content: center; }\n.algo-node { max-width: min(560px, 92%); text-align: center; padding: 9px 15px; border-radius: 11px; font-size: 0.85rem; line-height: 1.35; border: 1px solid #cbd5e1; background: #fff; color: #1e293b; box-shadow: 0 1px 2px rgba(15, 23, 42, .06); opacity: 0; animation: algo-pop .5s ease forwards; }\n.algo-node.start { background: var(--accent, #236ded); color: #fff; border-color: transparent; font-weight: 700; }\n.algo-node.dec { background: #fff6e6; border-color: #f2c879; color: #8a5a08; font-weight: 600; }\n.algo-node.proc { background: #eef5fb; border-color: #c7d9f5; }\n.algo-node.end { background: #e9f8ef; border-color: #a9dcbc; color: var(--secondary-dark); font-weight: 600; }\n.algo-arrow { width: 2px; height: 18px; margin: 3px auto; background: #94a3b8; position: relative; opacity: 0; animation: algo-fade .4s ease forwards; }\n.algo-arrow::after { content: \"\"; position: absolute; left: 50%; bottom: -1px; width: 8px; height: 8px; border-right: 2px solid #94a3b8; border-bottom: 2px solid #94a3b8; transform: translateX(-50%) rotate(45deg); }\n.algo-arrow.mini { height: 12px; }\n.algo-fork { display: flex; gap: 12px; justify-content: center; flex-wrap: wrap; margin-top: 4px; }\n.algo-branch { flex: 1 1 210px; max-width: 330px; display: flex; flex-direction: column; align-items: stretch; gap: 4px; }\n.algo-branch .algo-node { max-width: none; }\n.algo-label { align-self: center; font-size: 0.7rem; font-weight: 800; text-transform: uppercase; letter-spacing: .03em; color: var(--accent, #236ded); background: #fff; border: 1px solid #d4e3ee; border-radius: 999px; padding: 2px 11px; margin-bottom: 2px; opacity: 0; animation: algo-fade .4s ease forwards; }\n@keyframes algo-pop { from { opacity: 0; transform: translateY(9px) scale(.97); } to { opacity: 1; transform: none; } }\n@keyframes algo-fade { from { opacity: 0; } to { opacity: 1; } }\n@media (prefers-reduced-motion: reduce) {\n    .algo-node, .algo-arrow, .algo-label { opacity: 1 !important; animation: none !important; }\n}\n\n/* ── Track with no authored summaries yet ─────────────────────────────────\n   Shown in place of the whole guided path when the signed-in student's track\n   has no content loaded. Arabic/RTL, since it is the only Arabic surface on an\n   otherwise English page — it speaks to the student, not to the material. */\n.summaries-hub .hub-comingsoon {\n    max-width: 560px;\n    margin: 56px auto;\n    padding: 34px 30px;\n    border-radius: 18px;\n    border: 1px solid var(--border-color, #e2e8f0);\n    background: var(--surface, #fff);\n    text-align: center;\n}\n\n.summaries-hub .hub-comingsoon-icon {\n    display: grid;\n    place-items: center;\n    width: 66px;\n    height: 66px;\n    margin: 0 auto 18px;\n    border-radius: 18px;\n    background: linear-gradient(135deg, #f59e0b, #f97316);\n    color: #fff;\n}\n\n.summaries-hub .hub-comingsoon h1 {\n    margin: 0 0 12px;\n    font-size: 1.35rem;\n    font-weight: 800;\n    line-height: 1.5;\n    color: var(--text-dark, #0f1e3d);\n}\n\n.summaries-hub .hub-comingsoon p {\n    margin: 0 0 10px;\n    font-size: 0.95rem;\n    line-height: 1.9;\n    color: var(--text-medium, #475569);\n}\n\n.summaries-hub .hub-comingsoon-note {\n    margin-top: 16px !important;\n    padding-top: 14px;\n    border-top: 1px solid var(--border-color, #e2e8f0);\n    font-size: 0.86rem !important;\n    color: var(--muted, #64748b) !important;\n}\n\n/* The hub chrome is RTL Arabic while the study material stays English. These\n   keep mixed-direction lines (an Arabic sentence containing an English step\n   title) from breaking their alignment. */\n.summaries-hub[dir=\"rtl\"] .hub-lead,\n.summaries-hub[dir=\"rtl\"] .hub-head h1,\n.summaries-hub[dir=\"rtl\"] .hub-eyebrow { text-align: right; }\n\n.summaries-hub[dir=\"rtl\"] .hub-facts,\n.summaries-hub[dir=\"rtl\"] .hub-track-top { justify-content: flex-start; }\n\n/* Authored English inside an Arabic block: isolate so punctuation and numbers\n   don't jump to the wrong end of the line. */\n.summaries-hub[dir=\"rtl\"] [dir=\"ltr\"] {\n    unicode-bidi: isolate;\n    text-align: left;\n}\n\n/* The modal's chrome follows the site language; the summary body and the\n   practice questions inside it carry their own dir=\"ltr\", because that\n   material is English in both languages. */\n.sum-doc,\n.sub-summary,\n.sq-card { direction: ltr; text-align: left; }\n\n/* ── Deck blocks relocated next to their topic ────────────────────────────\n   Tables, algorithms and topic-cards used to be dumped in one trailing\n   \"study deck\" section, far from the heading they explain. They now sit at\n   the end of their own <h3> section; this wrapper gives them a little\n   separation from the prose above without turning into a second page. */\n.sum-doc .topic-deck {\n    display: flex;\n    flex-direction: column;\n    gap: 16px;\n    margin: 18px 0 26px;\n    padding-top: 16px;\n    border-top: 1px dashed var(--border-color, #d4deee);\n}\n\n.sum-doc .topic-deck > *:first-child { margin-top: 0; }\n.sum-doc .topic-deck > *:last-child { margin-bottom: 0; }\n\n/* The h4 that labels a card group shouldn't read as a new major topic now\n   that it sits inside a section rather than in a flat list. */\n.sum-doc .topic-deck .deck-topic {\n    margin: 4px 0 0;\n    font-size: 0.98rem;\n    color: var(--text-medium, #475569);\n}\n\n/* What's left in the shared section is genuinely cross-topic, so it reads as\n   an appendix rather than the main event. */\n.sum-doc .deck-enrich { margin-top: 30px; }\n\n/* ── Locked steps ──────────────────────────────────────────────────────────\n   Everything but the first lesson of a specialty, for a non-subscriber. The\n   title and the \"why\" stay visible on purpose: someone deciding whether to pay\n   should be able to see what they would be paying for. Muted rather than\n   crossed out — this is a preview of the subscription, not a rejection. */\n.path-step.is-locked .step-card {\n    background: rgba(15, 23, 42, 0.02);\n    border-style: dashed;\n}\n\n.path-step.is-locked .step-title,\n.path-step.is-locked .step-why {\n    color: var(--text-light);\n}\n\n.path-step.is-locked .step-node {\n    background: rgba(15, 23, 42, 0.06);\n    color: #8494ab;\n    box-shadow: none;\n}\n\n.step-state.is-locked {\n    color: #4b5c75;\n    background: rgba(15, 23, 42, 0.07);\n}\n\n.step-cta.is-locked {\n    background: var(--accent);\n    color: #ffffff;\n    border-color: transparent;\n}\n\n.step-cta.is-locked:hover {\n    filter: brightness(1.06);\n}\n\n/* \"Always free\" marker on the one open lesson in each specialty. */\n.step-state.is-free {\n    color: var(--secondary-dark);\n    background: rgba(22, 163, 74, 0.13);\n}\n";
